INSERT INTO startups (slug, name, logo_url, one_liner, sector, city, founded_year, entity_type, website, problem, solution, business_model, target_market, competition, revenue_band, months_running, customers, growth_pct, milestones, raise_min, raise_max, equity_offered, use_of_funds, prior_funding, founder_name, founder_role, founder_bio, founder_photo, linkedin, team_size, deck_url, video_url, featured, published) VALUES
('chai-theory', 'Chai Theory', NULL, 'A modern chai cafe chain doing PKR 2.8M a month across three Karachi locations.', 'F&B', 'Karachi', 2021, 'Private Limited', 'https://chaitheory.pk', 'Karachi''s young professionals have nowhere between a roadside dhaba and an expensive coffee franchise. The dhaba lacks comfort and hygiene; the franchise charges PKR 800 for a drink most people don''t actually want.', 'Clean, fast, air-conditioned chai cafes with a fixed 12-item menu, PKR 150–350 price band, and a 90-second serve time. Standardised recipes and central prep keep quality identical across branches.', 'Company-owned cafes. Average ticket PKR 480, 60% gross margin on beverages, 45% on food. A branch breaks even at month 7 on average.', 'Urban 20–35 year olds in Karachi''s commercial districts — an estimated 1.2M people within delivery radius of our current branches.', 'Quetta cafes on price, international coffee chains on ambience. Nobody owns the middle at scale.', 'PKR 2M–4M monthly', 34, '22,000+ monthly orders', '8% MoM', 'Third branch opened March 2025, profitable since month 9. Central kitchen commissioned January 2026.', 8000000, 10000000, '12–15%', 'Two new branches in Clifton and Gulshan (60%), central kitchen expansion (25%), hiring an operations manager (15%).', 0, 'Hamza Siddiqui', 'Founder & CEO', 'Ex-operations lead at a national restaurant group. Ran the first Chai Theory branch himself for a year before opening the second.', NULL, 'https://linkedin.com/in/hamzasiddiqui', 28, NULL, NULL, 1, 1),
('sastabazar', 'SastaBazar', NULL, 'Wholesale grocery marketplace for kiryana stores in Lahore, moving PKR 3.5M in monthly orders.', 'E-commerce', 'Lahore', 2022, 'Private Limited', 'https://sastabazar.pk', 'Lahore''s 40,000 kiryana stores buy stock through a chain of middlemen, losing 8–12% margin and half a working day per restock trip.', 'An Urdu-first ordering app plus next-morning delivery from our own micro-warehouse. Store owners order at 10pm, stock arrives before opening.', '6–9% margin on goods sold, plus placement fees from FMCG brands wanting shelf priority. Average order value PKR 18,000.', 'Kiryana and general stores in Lahore — 40,000 stores, PKR 30B+ annual restocking spend.', 'Traditional wholesale markets and two funded B2B players focused on Karachi. We win on delivery reliability and Urdu-first UX.', 'PKR 2M–4M monthly', 26, '640 active stores', '11% MoM', 'Crossed 600 active stores in April 2026. Repeat order rate 78%.', 6000000, 10000000, '10–14%', 'Second micro-warehouse (40%), inventory working capital (40%), two field sales hires (20%).', 1, 'Ayesha Tariq', 'Co-founder & CEO', 'Former category manager at a leading FMCG distributor. Grew up in her family''s kiryana store in Ichhra.', NULL, 'https://linkedin.com/in/ayeshatariq', 19, NULL, NULL, 1, 1),
('raftar-logistics', 'Raftar Logistics', NULL, 'Same-day intercity parcel delivery between Lahore, Faisalabad and Islamabad for e-commerce sellers.', 'Logistics', 'Faisalabad', 2021, 'Private Limited', 'https://raftar.pk', 'Online sellers in Punjab wait 3–5 days for courier delivery between major cities, driving return rates above 20% on cash-on-delivery orders.', 'Fixed daily line-haul vans between Lahore, Faisalabad and Islamabad with last-mile rider fleets in each city. Order by noon, delivered same evening.', 'Per-parcel pricing PKR 220–350 with volume tiers. COD collection fee of 1%. 34% net margin per parcel at current volume.', 'Punjab''s 25,000+ active online sellers shipping intercity daily.', 'National couriers on coverage; we beat them 4x on speed within our triangle and match on price.', 'PKR 1M–2M monthly', 30, '210 active seller accounts', '9% MoM', 'COD return rate for our sellers dropped from 22% to 9%. Islamabad route added November 2025.', 5000000, 8000000, '10–12%', 'Two additional line-haul vans (50%), rider fleet expansion (30%), route software (20%).', 0, 'Bilal Cheema', 'Founder & CEO', 'Third-generation transporter. Digitised his family''s goods-forwarding business before starting Raftar.', NULL, 'https://linkedin.com/in/bilalcheema', 42, NULL, NULL, 1, 1),
('ustaad-academy', 'Ustaad Academy', NULL, 'Matric and FSc exam prep in Urdu, sold through low-cost monthly subscriptions.', 'EdTech', 'Lahore', 2022, 'Private Limited', 'https://ustaad.pk', 'Board exam students outside major cities rely on academies charging PKR 5,000+ monthly, taught inconsistently, with no Urdu-medium digital alternative worth using.', 'Recorded video courses by top board examiners, weekly live problem-solving sessions, and past-paper drills — all in Urdu, at PKR 750 a month, working on 3G.', 'Monthly subscriptions with a 40% take rate on partner-academy bundles. Blended CAC PKR 380 against LTV of PKR 4,100.', '3.2M matric and FSc students sitting Punjab board exams annually.', 'English-first edtech apps and physical academies. Neither serves the Urdu-medium board student at this price.', 'PKR 1M–2M monthly', 22, '2,400 paying subscribers', '14% MoM in exam season', 'Students using the platform for 3+ months improved board scores by an average of 11%.', 4000000, 7000000, '8–12%', 'Content production for Sindh board syllabus (45%), performance marketing (35%), two academic hires (20%).', 0, 'Maryam Nawaz Khan', 'Co-founder & CEO', 'Taught FSc physics for eight years and ran Lahore''s highest-rated YouTube physics channel before founding Ustaad.', NULL, 'https://linkedin.com/in/maryamnkhan', 14, NULL, NULL, 1, 1),
('sehatlink', 'SehatLink', NULL, 'Lab test booking and home sample collection across Islamabad and Rawalpindi.', 'HealthTech', 'Islamabad', 2022, 'Private Limited', 'https://sehatlink.pk', 'Getting a blood test in the twin cities means queueing at a lab, opaque pricing, and paper reports that get lost between doctors.', 'Book any of 400+ tests in the app, a certified phlebotomist collects the sample at home, and digital reports arrive with plain-Urdu explanations of results.', '15–22% commission from partner labs plus a PKR 300 home collection fee. Corporate wellness packages for offices launched in 2025.', '2.3M residents of Islamabad and Rawalpindi; 60,000+ diagnostic tests performed daily in the twin cities.', 'Lab walk-ins and two national aggregator apps with thin coverage here. We own the phlebotomist network locally.', 'PKR 1M–2M monthly', 25, '9,800 completed bookings, 41% repeat', '10% MoM', '12 corporate wellness contracts signed. Partnered with three of the five largest lab networks.', 5000000, 9000000, '10–15%', 'Phlebotomist fleet expansion to Lahore (50%), app rebuild (25%), corporate sales team (25%).', 1, 'Dr. Omar Farooq', 'Founder & CEO', 'MBBS with five years in hospital operations at a major Islamabad hospital. Built SehatLink after watching patients carry the same lost paper reports repeatedly.', NULL, 'https://linkedin.com/in/dromarfarooq', 31, NULL, NULL, 1, 1),
('kapraa', 'Kapraa', NULL, 'D2C menswear basics brand shipping 4,000+ orders a month from Faisalabad''s textile belt.', 'D2C Apparel', 'Faisalabad', 2021, 'Sole Proprietorship (converting to Pvt Ltd)', 'https://kapraa.pk', 'Quality men''s basics in Pakistan are either imported at import prices or local with inconsistent sizing and fabric that fades in five washes.', 'Combed-cotton tees, polos and trousers cut to a consistent Pakistani fit, made in Faisalabad, sold direct at half the price of mall brands.', 'D2C via website and Instagram, 55% gross margin, AOV PKR 3,400. COD is 70% of orders with a 6% return rate — well below category average.', 'Urban men 22–40 buying online — a segment spending an estimated PKR 25B annually.', 'Mall brands on brand recognition, Instagram sellers on price. We win on fit consistency and fabric quality at mid price.', 'PKR 2M–4M monthly', 38, '4,200 orders/month, 31% repeat', '7% MoM', 'Crossed 100,000 lifetime orders in May 2026. Launched trousers line February 2026.', 6000000, 10000000, '10–13%', 'Fabric inventory for winter line (50%), performance marketing (30%), a Lahore try-on studio (20%).', 0, 'Usman Riaz', 'Founder & CEO', 'Grew up on the floor of his father''s knitwear export unit. Started Kapraa with rejected-for-export stock and PKR 400,000.', NULL, 'https://linkedin.com/in/usmanriazkapraa', 16, NULL, NULL, 1, 1),
('fasal-tech', 'FasalTech', NULL, 'Soil testing and crop advisory for mid-size farms in central Punjab, paid per acre per season.', 'AgriTech', 'Faisalabad', 2022, 'Private Limited', 'https://fasaltech.pk', 'Punjab''s farmers over-apply fertiliser by 30–40% because nobody tests their soil, burning cash and yield at the same time.', 'Field teams run on-site soil tests and deliver a per-acre fertiliser and irrigation plan via WhatsApp voice notes in Punjabi, with mid-season check-ins.', 'PKR 1,200 per acre per season. Input suppliers pay referral margin on precisely-dosed fertiliser orders. 68% of farms renew for the next season.', '180,000 mid-size farms (12–100 acres) in central Punjab.', 'Government extension services on paper, nobody in practice. Input dealers advise but are conflicted — they profit from overuse.', 'PKR 300k–1M monthly', 24, '1,150 farms covering 21,000 acres', 'Seasonal — 40% season-over-season', 'Client farms averaged 12% yield improvement and 25% lower fertiliser spend across two wheat seasons.', 3000000, 6000000, '8–12%', 'Six more field agronomists (55%), a second soil lab in Sahiwal (30%), advisory app (15%).', 0, 'Zainab Akhtar', 'Co-founder & CEO', 'Agricultural sciences graduate from UAF. Ran extension programs for a fertiliser company before switching sides to work for the farmer.', NULL, 'https://linkedin.com/in/zainabakhtar', 18, NULL, NULL, 0, 1),
('dastarkhwan', 'Dastarkhwan', NULL, 'Home-style office lunch subscriptions delivering 900 meals a day in Islamabad.', 'F&B', 'Islamabad', 2023, 'Private Limited', 'https://dastarkhwan.pk', 'Office workers in Islamabad choose daily between expensive restaurant delivery and tiffin services with no hygiene standards or menu variety.', 'A central kitchen producing a rotating 20-dish weekly menu, delivered to offices on subscription at PKR 350 a meal, with published hygiene audits.', 'Weekly and monthly meal subscriptions, 38% gross margin. Corporate accounts (10+ meals daily) are 55% of volume and churn under 3% monthly.', '250,000 office workers in Islamabad''s commercial sectors.', 'Informal tiffin services and food delivery apps. We beat one on consistency and the other on price.', 'PKR 2M–4M monthly', 16, '900 meals/day, 34 corporate accounts', '12% MoM', 'Kitchen capacity doubled January 2026. First 1,000-meal day in June 2026.', 4000000, 8000000, '10–14%', 'Second kitchen in Rawalpindi (50%), delivery fleet (30%), corporate sales (20%).', 0, 'Sana Mirza', 'Founder & CEO', 'Former hotel F&B manager. Started Dastarkhwan from her own kitchen with 40 daily meals for one office building.', NULL, 'https://linkedin.com/in/sanamirza', 24, NULL, NULL, 0, 1),
('partsdukan', 'PartsDukan', NULL, 'Online auto parts marketplace with verified fitment for Pakistan''s most-driven cars.', 'E-commerce', 'Karachi', 2021, 'Private Limited', 'https://partsdukan.pk', 'Car owners get quoted three different prices for the same part and often receive the wrong one — fitment data for local models simply doesn''t exist online.', 'A catalogue of 18,000 parts mapped to exact make-model-year for the 30 most common cars in Pakistan, with a fitment guarantee and 48-hour delivery.', 'Marketplace take rate of 12% plus fulfilment fees. Own-inventory fast-movers carry 28% margin. AOV PKR 6,200.', '3.8M registered passenger cars in Karachi, Lahore and Islamabad.', 'Physical parts markets and general marketplaces with no fitment data. Our catalogue is the moat.', 'PKR 2M–4M monthly', 40, '3,100 orders/month', '6% MoM', 'Fitment-error return rate under 2%. Workshop bulk-ordering portal launched April 2026.', 7000000, 10000000, '12–16%', 'Fast-mover inventory (45%), catalogue expansion to bikes (30%), workshop sales team (25%).', 1, 'Adnan Qureshi', 'Co-founder & CEO', 'Ran his family''s parts shop in Plaza Market for six years, then spent two years building the fitment database that became PartsDukan.', NULL, 'https://linkedin.com/in/adnanqureshi', 22, NULL, NULL, 0, 1),
('qaabil', 'Qaabil', NULL, 'Job-ready IT bootcamps in Lahore with income-share agreements and an 81% placement rate.', 'EdTech', 'Lahore', 2022, 'Private Limited', 'https://qaabil.pk', 'Pakistan produces 25,000 CS graduates a year but companies still can''t hire — degrees don''t teach the stack employers actually use.', '16-week full-time bootcamps in web development and QA, taught by working engineers, paid via income-share after the graduate lands a job above PKR 60k/month.', 'Income-share agreements of 12% of salary for 18 months, capped at PKR 350,000. Upfront-fee track for self-funded students is 30% of enrolment.', 'Fresh graduates and career-switchers 20–28; roughly 400,000 people enter this pool annually.', 'Short-course academies with no placement accountability. Our incentive alignment is the difference.', 'PKR 1M–2M monthly', 27, '310 graduates, 81% placed within 90 days', 'New cohort size up 20% each quarter', 'Hiring partnerships with 40 software houses. First QA cohort fully placed before graduation.', 5000000, 9000000, '10–14%', 'ISA financing pool (60%), second campus in Johar Town (25%), placement team (15%).', 0, 'Fahad Malik', 'Co-founder & CEO', 'Former engineering manager at a US-remote software house. Hired 60+ engineers and got tired of interviewing unprepared graduates, so he built the pipeline himself.', NULL, 'https://linkedin.com/in/fahadmalik', 15, NULL, NULL, 0, 1),
('hisaab', 'Hisaab', NULL, 'Urdu bookkeeping app for small retailers — 6,000 shops track credit and cash daily.', 'E-commerce', 'Karachi', 2022, 'Private Limited', 'https://hisaab.pk', 'Small shopkeepers run credit ledgers in paper registers — money gets lost, disputes are constant, and no formal lender will touch a business with no records.', 'A dead-simple Urdu app for udhaar tracking, daily cash tally and automatic WhatsApp payment reminders to customers. Works offline, syncs when connected.', 'Freemium: core ledger free, PKR 500/month for reminders, reports and multi-user. Transaction data (with consent) powers a lending-referral pipeline with two partner fintechs.', '2M+ small retailers nationwide; 300,000 in Karachi alone.', 'Paper registers and two regional ledger apps. Retention is the battleground — ours is 64% at month 6.', 'PKR 300k–1M monthly', 21, '6,000 active shops, 850 paying', '15% MoM paid conversion growth', 'PKR 900M in receivables tracked through the app. Lending referral pilot live with 120 shops.', 4000000, 7000000, '8–12%', 'Field onboarding teams (45%), Android app performance work (30%), lending pipeline integrations (25%).', 1, 'Taha Ahmed', 'Co-founder & CEO', 'Ex-product manager at a Pakistani fintech unicorn. Built Hisaab''s first version in a weekend for his uncle''s general store.', NULL, 'https://linkedin.com/in/tahaahmed', 12, NULL, NULL, 0, 1),
('thanda-meetha', 'Thanda Meetha', NULL, 'Packaged traditional desserts sold through 300+ retail stores in Punjab.', 'F&B', 'Lahore', 2021, 'Private Limited', 'https://thandameetha.pk', 'Traditional desserts like kheer and gajar ka halwa are either homemade or sold loose at sweet shops with no shelf life, no branding and no consistency.', 'Factory-packed single-serve traditional desserts with 21-day refrigerated shelf life, stocked in supermarket chillers next to imported yogurts at half the price.', 'Distribution through modern trade and top general stores. 42% gross margin ex-factory. Listed in two national supermarket chains.', 'Urban grocery shoppers across Punjab; the packaged dessert category is growing 18% annually.', 'Loose sweet shops and imported desserts. We''re the only branded local player in the chiller.', 'PKR 1M–2M monthly', 36, '300+ stocking stores, 45,000 units/month', '5% MoM', 'Second national chain listing signed May 2026. Ramzan season sold out three weeks early.', 5000000, 8000000, '10–15%', 'Cold-chain van fleet (40%), production line automation (40%), trade marketing (20%).', 0, 'Khadija Imran', 'Founder & CEO', 'Food technologist who spent six years in dairy manufacturing before productising her grandmother''s kheer recipe.', NULL, 'https://linkedin.com/in/khadijaimran', 26, NULL, NULL, 0, 1),
('gharana', 'Gharana', NULL, 'Verified home services — plumbers, electricians, AC techs — completing 2,000 jobs a month in Karachi.', 'Logistics', 'Karachi', 2022, 'Private Limited', 'https://gharana.pk', 'Finding a plumber in Karachi means calling around, no-shows, made-up prices and letting an unverified stranger into your home.', 'Background-checked technicians, fixed published prices for 120 common jobs, booked in the app with a 2-hour arrival window and a 30-day workmanship guarantee.', '20% commission per job plus PKR 5,000/month technician subscription for lead priority. Average job value PKR 2,800.', '1.5M middle and upper-middle income households in Karachi.', 'Word-of-mouth technicians and one funded competitor focused on beauty services. Home repair is unclaimed.', 'PKR 1M–2M monthly', 23, '2,000 jobs/month, 4.6★ average rating', '13% MoM', '480 verified technicians onboarded. AC servicing season did 3x normal volume.', 5000000, 9000000, '10–14%', 'Technician recruitment and verification (40%), Lahore launch (40%), customer app v2 (20%).', 1, 'Shahzaib Baig', 'Co-founder & CEO', 'Former operations lead at a ride-hailing company''s Karachi office. Applied the same supply-side playbook to home services.', NULL, 'https://linkedin.com/in/shahzaibbaig', 20, NULL, NULL, 0, 1),
('mitti', 'Mitti', NULL, 'D2C skincare made from indigenous ingredients, 2,500 orders a month and growing.', 'D2C Apparel', 'Islamabad', 2023, 'Private Limited', 'https://mitti.pk', 'Pakistani skincare buyers choose between expensive imports and local products with undisclosed ingredients and no dermatological testing.', 'A tight 9-SKU line built on multani mitti, rosewater and cold-pressed oils — dermatologically tested, fully disclosed ingredients, priced PKR 900–2,200.', 'D2C website and Instagram, 62% gross margin, AOV PKR 2,900. Subscribe-and-save is 18% of revenue and climbing.', 'Urban women 20–40 buying skincare online — a PKR 15B and fast-growing segment.', 'Imported brands on prestige, bazaar products on price. We own ''trusted local'' with published lab tests.', 'PKR 1M–2M monthly', 14, '2,500 orders/month, 36% repeat', '16% MoM', 'Sold out launch batch in 11 days. Featured by three of Pakistan''s top beauty creators unpaid.', 3000000, 6000000, '8–12%', 'Inventory depth (45%), content and creator marketing (35%), pharmacy retail pilot (20%).', 0, 'Noor Fatima', 'Founder & CEO', 'Pharmacist by training. Formulated Mitti''s first three products herself and had them independently lab-tested before selling a single unit.', NULL, 'https://linkedin.com/in/noorfatima', 9, NULL, NULL, 0, 1),
('murghikhana', 'MurghiKhana', NULL, 'Farm-to-door antibiotic-free chicken, delivering to 1,800 households in Lahore weekly.', 'AgriTech', 'Lahore', 2022, 'Private Limited', 'https://murghikhana.pk', 'Urban families increasingly distrust commercial broiler chicken but have no reliable, affordable alternative to the neighbourhood murghi wala.', 'Contracted small farms raise antibiotic-free birds to our protocol; we process, chill and deliver cut-to-order within 24 hours of slaughter on weekly subscriptions.', 'Weekly subscription boxes PKR 1,800–4,500. 30% gross margin after farm cost and processing. Subscriber churn 4% monthly.', 'Upper-middle income households in Lahore — 400,000 households, protein spend PKR 15,000+/month.', 'Wet market butchers on price and habit. We win on trust, and our farm audits are public.', 'PKR 2M–4M monthly', 20, '1,800 weekly subscriber households', '9% MoM', 'Contracted farm network grew to 14 farms. Launched marinated ready-to-cook line March 2026.', 6000000, 10000000, '12–16%', 'Processing facility upgrade (50%), cold-chain delivery vans (30%), farm network expansion (20%).', 0, 'Ali Raza Gillani', 'Co-founder & CEO', 'Veterinary sciences graduate who managed poultry operations for a feed conglomerate before building the supply chain he wished existed.', NULL, 'https://linkedin.com/in/aliragillani', 27, NULL, NULL, 0, 1),
('safar-stays', 'Safar Stays', NULL, 'Managed guesthouse network in northern Pakistan with 68% average occupancy.', 'E-commerce', 'Islamabad', 2021, 'Private Limited', 'https://safarstays.pk', 'Domestic tourism to the north has exploded but booking a room in Hunza or Skardu still means WhatsApp roulette with unverified properties and no refunds.', 'We sign underperforming guesthouses, standardise them to a published checklist, professionally photograph them, and run pricing, booking and payments centrally.', '18–25% of room revenue on managed properties. Instant-confirmation bookings with digital payment, prepaid, with a clear refund policy.', '1.5M+ domestic tourists visiting Gilgit-Baltistan annually, growing 20%+ a year.', 'Direct WhatsApp booking and international OTAs with stale inventory. Our managed model controls quality end to end.', 'PKR 1M–2M monthly', 32, '34 managed properties, 11,000 room-nights sold', 'Seasonal — 30% YoY', '68% average occupancy across the network vs 40% regional average. Skardu cluster added 2025.', 6000000, 10000000, '12–15%', 'Property onboarding in Swat and Naran (50%), booking platform v2 (30%), regional ops hires (20%).', 1, 'Danish Hussain', 'Founder & CEO', 'Former hotel revenue manager from Gilgit. Managed his family''s guesthouse to 90% seasonal occupancy before productising the playbook.', NULL, 'https://linkedin.com/in/danishhussain', 21, NULL, NULL, 0, 1);
